exports.buildStreamGraphMermaid = buildStreamGraphMermaid;
function buildStreamGraphMermaid(nodes, edges) {
    let mermaid = "flowchart LR\n";
    const nodeIdToMermaid = new Map();
    nodes.forEach((n, i) => {
        const id = "N" + i;
        nodeIdToMermaid.set(n.nodeId, id);
        mermaid += `  ${id}["${n.nodeId}"]\n`;
    });
    const byOutput = new Map();
    const byInput = new Map();
    nodes.forEach((n) => {
        const mid = nodeIdToMermaid.get(n.nodeId);
        if (mid) {
            if (n.outputType)
                byOutput.set(n.outputType, mid);
            byInput.set(n.inputType, mid);
        }
    });
    edges.forEach((e) => {
        const fromNode = byOutput.get(e.from);
        const toNode = byInput.get(e.to);
        if (fromNode && toNode)
            mermaid += `  ${fromNode} --> ${toNode}\n`;
    });
    return mermaid;
}
